import {CATEGORIES,WARDS,CHANNELS,TEAMS,STATUSES,HOURS,NEXT,seed,createRequest,transition,assign,sla,dueAt,metrics,filterRequests,rice,experiment,csv} from './domain.js';
const $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const KEY='jansetu-v1';let rows,storageWarning=false;
try{const data=JSON.parse(localStorage.getItem(KEY));rows=Array.isArray(data)&&data.length&&data.every(r=>STATUSES.includes(r.status)&&HOURS[r.priority]&&Array.isArray(r.history)&&Number.isFinite(r.createdAt))?data:seed();}catch{rows=seed();storageWarning=true;}
let filters={query:'',status:'',ward:'',category:''},labMode='roadmap',selectedId=null;
const roadmap=[{name:'Resolution evidence + reopen',reach:240,impact:3,confidence:.8,effort:3},{name:'SLA queue and named owner',reach:360,impact:2,confidence:.8,effort:2},{name:'Low-connectivity field intake',reach:120,impact:2,confidence:.5,effort:4},{name:'Automated SMS updates',reach:280,impact:1,confidence:.5,effort:3}];
const pct=n=>n===null?'—':Math.round(n*100)+'%', date=n=>new Date(n).toLocaleString('en-IN',{day:'2-digit',month:'short',hour:'2-digit',minute:'2-digit'});
const options=(list,value='',placeholder='')=>(placeholder?`<option value="">${placeholder}</option>`:'')+list.map(v=>`<option ${v===value?'selected':''} value="${esc(v)}">${esc(v)}</option>`).join('');
function toast(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').style.display='none',5000);}
function persist(){try{localStorage.setItem(KEY,JSON.stringify(rows));}catch{storageWarning=true;toast('Browser storage unavailable. Changes last only for this session; export before leaving.');}$('#nav-count').textContent=metrics(rows).open;}
const badge=(t)=>`<span class="pill ${['Overdue','Missed','Critical','Reopened'].includes(t)?'red':['At risk','High'].includes(t)?'amber':['Resolved','Met'].includes(t)?'green':['Assigned','In progress'].includes(t)?'blue':''}">${esc(t)}</span>`;
const head=(title,sub,buttons='')=>`<div class="pagehead"><div><h1>${title}</h1><p class="sub">${sub}</p></div><div class="actions">${buttons}</div></div>`;
const addBtn='<a class="btn primary" href="#intake">＋ New request</a>';
const exportBtn='<button class="btn" data-export>↓ Export CSV</button>';
function cards(m){return `<section class="metrics" aria-label="Service metrics"><div class="metric"><div class="label">Active requests <span>↗</span></div><strong>${m.open}</strong><small>Across ${WARDS.length} demonstration wards</small></div><div class="metric warn"><div class="label">Overdue requests <span>◷</span></div><strong>${m.overdue}</strong><small>${m.atRisk} more due within 12 hours</small></div><div class="metric"><div class="label">Resolved within SLA <span>✓</span></div><strong>${pct(m.onTimeRate)}</strong><small>${m.onTime} of ${m.resolved} currently resolved requests</small></div><div class="metric"><div class="label">Median resolution time <span>⌁</span></div><strong>${m.medianHours===null?'—':m.medianHours.toFixed(1)+'<span style="font-size:16px;letter-spacing:0"> h</span>'}</strong><small>Currently resolved requests only</small></div></section>`;}
function table(list,compact=false){return `<div class="tablewrap"><table><thead><tr><th>Request</th><th>${compact?'Priority':'Ward / channel'}</th><th>Status</th><th>SLA</th></tr></thead><tbody>${list.map(r=>`<tr><td><button class="titlebtn" data-id="${esc(r.id)}">${esc(r.title)}</button><small>${esc(r.id)} · ${esc(r.category)}</small></td><td>${compact?badge(r.priority):`${esc(r.ward)}<small>${esc(r.channel)}</small>`}</td><td>${badge(r.status)}</td><td>${badge(sla(r))}</td></tr>`).join('')}</tbody></table>${list.length?'':'<div class="empty">No matching requests. Try clearing your filters.</div>'}</div>`;}
function meter(label,n,total,color=''){return `<div class="meterrow"><div class="meterlabel"><span>${esc(label)}</span><b>${n}${total?' / '+total:''}</b></div><div class="meter"><span style="width:${total?n/total*100:0}%;${color?'background:'+color:''}"></span></div></div>`;}
function overview(){const m=metrics(rows),urgent=rows.filter(r=>r.status!=='Resolved').sort((a,b)=>dueAt(a)-dueAt(b)).slice(0,5);return head('Every request. A clear next step.','Track service delivery, spot delays, and keep teams accountable.',exportBtn+addBtn)+`<section class="hero"><div><div class="eyebrow">FROM INTAKE TO ACCOUNTABILITY</div><h2>Better service starts with<br>a request that doesn’t get lost.</h2><p>A working product prototype for civic service teams. Explore ${rows.length} synthetic requests, take ownership, and follow a resolution through.</p><a class="btn small" href="#case">Explore the product story <span>↗</span></a></div><div class="heroart" aria-hidden="true"><div class="orbit"><strong>✓</strong></div></div></section>`+cards(m)+`<div class="grid"><section class="panel"><div class="panelhead"><div><h2>Needs attention</h2><p class="sub">Open requests, earliest deadline first</p></div><a class="btn small" href="#requests">View queue ↗</a></div>${table(urgent,true)}</section><section class="panel"><div class="panelhead"><div><h2>Workload by service</h2><p class="sub">Active requests across all wards</p></div></div><div class="panelbody">${CATEGORIES.map(c=>meter(c,rows.filter(r=>r.category===c&&r.status!=='Resolved').length,m.open)).join('')}<div class="note">A closed ticket is not the end of the journey. Requests can be reopened with a reason, preserving the original deadline.</div></div></section></div><p class="compact">Sample data is generated for demonstration. These metrics are computed from this browser’s records and are not field results.</p>`;}
function requests(){return head('The request queue','One place for ownership, service deadlines, and resolution history.',exportBtn+addBtn)+`<section class="panel"><div class="filters"><input id="query" aria-label="Search requests" placeholder="Search request ID or issue…" value="${esc(filters.query)}"><select id="filter-status" aria-label="Filter status">${options(STATUSES,filters.status,'All statuses')}</select><select id="filter-ward" aria-label="Filter ward">${options(WARDS,filters.ward,'All wards')}</select><select id="filter-category" aria-label="Filter category">${options(CATEGORIES,filters.category,'All services')}</select><button class="btn small" id="clear">Clear</button></div><div id="queue-results">${queueResults()}</div></section>`;}
function queueResults(){const list=filterRequests(rows,filters).sort((a,b)=>b.createdAt-a.createdAt);return `<div class="panelhead"><span class="sub">${list.length} requests · newest first</span><span class="sub">Select an issue to take action</span></div>${table(list)}`;}
function intake(){return head('Make the first step simple.','Capture a service issue from a web form, help desk, or field visit.')+`<div class="grid"><section class="panel"><div class="panelhead"><h2>New service request</h2><span class="pill">No personal details needed</span></div><form id="intake-form" class="panelbody formgrid"><label class="full">Issue title<input name="title" required minlength="8" maxlength="100" placeholder="e.g. Street lights out near the community centre"></label><label>Service<select name="category">${options(CATEGORIES)}</select></label><label>Ward<select name="ward">${options(WARDS)}</select></label><label>Intake channel<select name="channel">${options(CHANNELS)}</select></label><label>Service priority<select name="priority">${options(['Normal','High','Critical'])}</select><small>Normal: 120 h · High: 48 h · Critical: 24 h</small></label><label class="full">What needs to be resolved?<textarea name="description" required minlength="20" maxlength="1000" placeholder="Describe the disruption and public landmark. Use fictional details in this demo."></textarea></label><p class="sub full">Priority and SLA durations are prototype assumptions, not official government standards. This demo does not submit requests to any authority.</p><div class="full error" id="form-error" role="alert"></div><div class="full"><button class="btn primary" type="submit">Create request →</button></div></form></section><aside class="panel"><div class="panelhead"><h2>Designed for a complete journey</h2></div><div class="panelbody"><div class="step"><h3>01 · Capture</h3><p>A consistent form across three intake channels.</p></div><div class="step"><h3>02 · Own</h3><p>Assign a responsible team before work starts.</p></div><div class="step"><h3>03 · Resolve</h3><p>Require a meaningful evidence note to close.</p></div><div class="step"><h3>04 · Listen again</h3><p>Reopen with a reason if the issue remains.</p></div><div class="note">Channel selection records where a request originated. WhatsApp, SMS and government integrations are outside this prototype.</div></div></aside></div>`;}
function insights(){const m=metrics(rows);return head('Measure service, not just activity.','Transparent definitions. Visible denominators. No invented impact.',exportBtn)+cards(m)+`<div class="grid"><section class="panel"><div class="panelhead"><h2>Service health by ward</h2><span class="pill">All records</span></div><div class="tablewrap"><table><thead><tr><th>Ward</th><th>Active</th><th>Overdue</th><th>On-time / resolved</th></tr></thead><tbody>${WARDS.map(w=>{const n=metrics(rows.filter(r=>r.ward===w));return `<tr><td>${w}</td><td>${n.open}</td><td>${n.overdue}</td><td>${n.onTime} / ${n.resolved} <small>${pct(n.onTimeRate)}</small></td></tr>`;}).join('')}</tbody></table></div><div class="panelbody"><div class="note">Workload differences do not establish performance differences. Priority mix, staffing and case complexity are not controlled.</div></div></section><section class="panel"><div class="panelhead"><h2>Intake channel mix</h2></div><div class="panelbody">${CHANNELS.map(c=>meter(c,rows.filter(r=>r.channel===c).length,rows.length)).join('')}<p class="legend">Channels are source labels, not live external integrations.</p></div></section></div><div class="grid"><section class="panel"><div class="panelhead"><h2>Current workflow distribution</h2></div><div class="panelbody">${STATUSES.map(s=>meter(s,rows.filter(r=>r.status===s).length,rows.length)).join('')}<p class="legend">A snapshot of current states, not a conversion funnel. Reopened requests can move through the journey more than once.</p></div></section><section class="panel"><div class="panelhead"><h2>Quality guardrails</h2></div><div class="panelbody"><div class="metric"><div class="label">Requests ever reopened</div><strong>${m.reopened} / ${m.total}</strong><small>Counts requests, not reopening events</small></div><ul class="checklist"><li>On-time rate = currently resolved within original SLA ÷ currently resolved.</li><li>Median time = median hours from creation to most recent resolution, for currently resolved requests.</li><li>Reopened requests return to the active queue and keep their original deadline.</li><li>Actual impact requires a real pilot and a comparable baseline.</li></ul></div></section></div>`;}
function lab(){return head('Make the trade-offs visible.','Prioritisation and experimentation tools for a product review.')+`<div class="tabbar"><button class="btn ${labMode==='roadmap'?'selected':''}" data-lab="roadmap">Roadmap priorities</button><button class="btn ${labMode==='experiment'?'selected':''}" data-lab="experiment">Experiment workbench</button></div>`+(labMode==='roadmap'?roadmapView():experimentView());}
function roadmapView(){return `<div class="grid"><section class="panel"><div class="panelhead"><h2>What should we build next?</h2><span class="pill">Editable assumptions</span></div><div class="panelbody"><label>Evidence + reopen: estimated effort (person-weeks)<input id="effort" type="range" min="1" max="8" step="1" value="${roadmap[0].effort}"><small id="effort-label">${roadmap[0].effort} person-weeks</small></label></div><div id="roadmap-table">${riceTable()}</div></section><section class="panel"><div class="panelhead"><h2>RICE is a conversation starter.</h2></div><div class="panelbody"><p class="compact">Score = reach × impact × confidence ÷ effort. Reach means estimated requests affected per month; confidence is a fraction; effort is person-weeks.</p><div class="note">All inputs are planning hypotheses. Move the effort slider to see the ranking change. Safety and workflow dependencies can override rank.</div><ul class="checklist"><li><b>Now:</b> accountable ownership, SLA visibility, evidence and reopening.</li><li><b>Next:</b> test field usability and accessibility with consenting participants.</li><li><b>Later:</b> authentication, durable backend, multilingual content and delivery integrations.</li></ul><p class="compact">Evidence is included in the MVP even if its score falls: closure quality is a release requirement.</p></div></section></div>`;}
function riceTable(){return `<div class="tablewrap"><table><thead><tr><th>Feature</th><th>Reach</th><th>Impact</th><th>Confidence</th><th>Effort</th><th>RICE</th></tr></thead><tbody>${[...roadmap].sort((a,b)=>rice(b)-rice(a)).map(r=>`<tr><td>${r.name}</td><td>${r.reach}</td><td>${r.impact}</td><td>${pct(r.confidence)}</td><td>${r.effort}</td><td><b>${rice(r).toFixed(1)}</b></td></tr>`).join('')}</tbody></table></div>`;}
function experimentView(){return `<div class="grid"><section class="panel"><div class="panelhead"><h2>Would guided intake improve completion?</h2><span class="pill">Illustrative counts</span></div><form id="experiment" class="panelbody"><div class="formgrid"><label>A · sessions<input name="an" type="number" min="1" max="10000000" step="1" value="200" required></label><label>A · completions<input name="ay" type="number" min="0" max="10000000" step="1" value="120" required></label><label>B · sessions<input name="bn" type="number" min="1" max="10000000" step="1" value="200" required></label><label>B · completions<input name="by" type="number" min="0" max="10000000" step="1" value="142" required></label></div><p class="compact">A: longer form. B: guided form. These are hypothetical independent sessions, not collected user data.</p><button class="btn primary">Evaluate difference</button><div id="experiment-error" class="error" role="alert"></div><div id="experiment-result" aria-live="polite"></div></form></section><section class="panel"><div class="panelhead"><h2>Decide before the data arrives.</h2></div><div class="panelbody"><ul class="checklist"><li><b>Primary metric:</b> valid submission / unique eligible session.</li><li><b>Randomisation:</b> stable assignment per participant; one analysed session per participant.</li><li><b>Guardrails:</b> invalid requests, completion time, accessibility failures.</li><li><b>Planning:</b> predefine sample size from baseline and minimum worthwhile effect; do not stop on a favourable interim result.</li><li><b>Rollout:</b> progress only if quality guardrails and operational capacity also pass.</li></ul><div class="note">This calculator uses an approximate 95% normal interval for an independent difference in proportions. Small counts need an alternative method. It does not prove causality without a sound experiment.</div></div></section></div>`;}
function caseStudy(){return head('A product case study, with a working core.','Independent project · Rishabh Sharda · October 2026')+`<section class="hero"><div><div class="eyebrow">JANSETU / FROM PROBLEM TO PRODUCT</div><h2 class="caseintro">How might we make a service request easy to own—and hard to quietly forget?</h2><p>A civic operations prototype built around a complete workflow, transparent measurement, and explicit product decisions.</p><div class="statstrip"><span>72 synthetic requests</span><span>5 workflow states</span><span>4 service categories</span></div></div></section><div class="casecards"><section class="panel panelbody"><div class="number">01</div><h3>Problem hypothesis</h3><p>When intake is scattered, teams may lose ownership and residents may receive unclear updates. This is a hypothesis to validate, not a finding from interviews.</p><h3>Target users</h3><p>Help-desk operator, service coordinator and field responder. A resident-facing portal is a later extension.</p></section><section class="panel panelbody"><div class="number">02</div><h3>Product decision</h3><p>Start with one complete operational loop: capture → assign → work → resolve → reopen. Make queue urgency explainable with transparent SLA rules.</p><h3>Deliberate scope</h3><p>Browser-local prototype. No accounts, political profiling, personal details, notification delivery or government integrations.</p></section><section class="panel panelbody"><div class="number">03</div><h3>Success and evidence</h3><p>Target a higher share of genuinely resolved requests within SLA. Track reopenings and closure quality as guardrails.</p><h3>What is established?</h3><p>A functional prototype and tested business rules. No claim of live adoption, measured time savings, or completed field research.</p></section></div><div class="grid" style="margin-top:24px"><section class="panel"><div class="panelhead"><h2>Built for a product associate’s work</h2></div><div class="tablewrap"><table><thead><tr><th>Responsibility</th><th>Evidence in this project</th></tr></thead><tbody><tr><td>Strategy & roadmap</td><td>Problem framing, RICE trade-offs, staged rollout</td></tr><tr><td>User journey</td><td>Cross-channel intake metadata and complete service lifecycle</td></tr><tr><td>Requirements</td><td>PRD, explicit scope, state machine and data definitions</td></tr><tr><td>Acceptance testing</td><td>Executable rule tests and a manual UAT matrix</td></tr><tr><td>Operationalisation</td><td>Team ownership, evidence gate, reopening and SLA queue</td></tr></tbody></table></div></section><section class="panel"><div class="panelhead"><h2>A practical validation plan</h2></div><div class="panelbody"><div class="step"><h3>Discover</h3><p>Interview five consenting operators. Reconstruct their last difficult handoff without collecting resident identities.</p></div><div class="step"><h3>Test</h3><p>Run five task-based usability sessions. Measure task success, errors, and time to assign.</p></div><div class="step"><h3>Pilot</h3><p>Only after secure backend and access controls: one team, two weeks, explicit baseline and review of closure quality.</p></div><div class="note">Domain reference: CPGRAMS publicly describes tracking and appeals. JanSetu is an independent local-service concept, not a clone or integration. <a class="link" href="https://pgportal.gov.in/" target="_blank" rel="noopener">Reference ↗</a></div></div></section></div><section class="panel"><div class="panelhead"><h2>Try a 90-second walkthrough</h2></div><div class="panelbody"><p class="compact">Create a request → assign a team → start work → add a resolution note → reopen with a reason → check the queue and metrics. Then change the roadmap effort estimate and evaluate the example experiment.</p><div class="actions">${addBtn}<a class="btn" href="#lab">Explore product lab</a><button class="btn" id="reset">Reset synthetic demo</button></div><p class="legend">Reset replaces this browser’s demo records only. Export CSV first if you want to retain your changes.</p></div></section>`;}
function openDetail(id){const r=rows.find(r=>r.id===id);if(!r)return;selectedId=id;const d=$('#detail');d.innerHTML=`<div class="detailhead"><div><div class="eyebrow">${esc(r.id)} · ${esc(r.category)}</div><h2 id="detail-title">${esc(r.title)}</h2></div><button class="btn small" id="close-detail" aria-label="Close request details">✕</button></div><div class="detailbody"><div class="actions">${badge(r.status)}${badge(r.priority)}${badge(sla(r))}</div><p class="compact">${esc(r.description)}</p><div class="meta"><div><small>Ward</small><b>${esc(r.ward)}</b></div><div><small>Source</small><b>${esc(r.channel)}</b></div><div><small>Owner</small><b>${esc(r.assignee||'Unassigned')}</b></div><div><small>Created</small><b>${date(r.createdAt)}</b></div><div><small>Original deadline</small><b>${date(dueAt(r))}</b></div><div><small>Reopenings</small><b>${r.reopenCount}</b></div></div>${r.status!=='Resolved'?`<form id="assign-form" class="actions"><label style="flex:1">Response team<select name="assignee" required>${options(TEAMS,r.assignee,'Choose a team')}</select></label><button class="btn" style="align-self:end">${r.status==='New'?'Assign request':'Update owner'}</button></form>`:''}${r.status!=='New'?`<hr class="divider"><form id="transition-form"><label>Next step<select name="status">${options(NEXT[r.status])}</select></label><label style="margin-top:15px">Resolution evidence / update note<textarea name="note" maxlength="1000" placeholder="For closure or reopening, describe the work checked or issue remaining (at least 15 characters)."></textarea></label><button class="btn primary" style="margin-top:12px">Save update →</button></form>`:''}<div id="detail-error" class="error" role="alert"></div><hr class="divider"><h3>Request history</h3><ol class="timeline">${r.history.map(h=>`<li><b>${esc(h.action)}</b><small>${date(h.at)}</small>${esc(h.note)}</li>`).join('')}</ol><p class="legend">This audit-style history is browser-local and editable through developer tools. Production would require server-side enforcement.</p></div>`;if(!d.open)d.showModal();$('#close-detail').onclick=()=>d.close();const af=$('#assign-form');if(af)af.onsubmit=e=>{e.preventDefault();updateRecord(()=>assign(r,new FormData(af).get('assignee')));};const tf=$('#transition-form');if(tf)tf.onsubmit=e=>{e.preventDefault();const f=new FormData(tf);updateRecord(()=>transition(r,f.get('status'),{note:f.get('note')}));};}
function updateRecord(fn){try{const updated=fn();rows=rows.map(r=>r.id===updated.id?updated:r);persist();render();openDetail(updated.id);toast('Request updated. History preserved.');}catch(e){$('#detail-error').textContent=e.message;}}
function download(){const list=location.hash==='#requests'?filterRequests(rows,filters):rows;const url=URL.createObjectURL(new Blob([csv(list)],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download='jansetu-requests.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast(`${list.length} requests exported.`);}
function render(){const page=location.hash.slice(1)||'overview';const titles={overview:'Overview',requests:'Request queue',intake:'New request',insights:'Service insights',lab:'Product lab',case:'Case study'};$('#crumb').textContent=titles[page]||'Overview';document.querySelectorAll('nav a').forEach(a=>{a.classList.toggle('active',a.dataset.page===page);if(a.dataset.page===page)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current');});$('#main').innerHTML=({overview,requests,intake,insights,lab,case:caseStudy}[page]||overview)();$('#nav-count').textContent=metrics(rows).open;
 if(page==='requests'){$('#query').oninput=e=>{filters.query=e.target.value;$('#queue-results').innerHTML=queueResults();};for(const k of ['status','ward','category'])$('#filter-'+k).onchange=e=>{filters[k]=e.target.value;$('#queue-results').innerHTML=queueResults();};$('#clear').onclick=()=>{filters={query:'',status:'',ward:'',category:''};render();};}
 if(page==='intake')$('#intake-form').onsubmit=e=>{e.preventDefault();try{const r=createRequest(Object.fromEntries(new FormData(e.target)));rows.unshift(r);persist();location.hash='requests';openDetail(r.id);toast('Request created. Assign a response team to continue.');}catch(err){$('#form-error').textContent=err.message;}};
 if(page==='lab'){document.querySelectorAll('[data-lab]').forEach(b=>b.onclick=()=>{labMode=b.dataset.lab;render();});if(labMode==='roadmap')$('#effort').oninput=e=>{roadmap[0].effort=Number(e.target.value);$('#effort-label').textContent=e.target.value+' person-weeks';$('#roadmap-table').innerHTML=riceTable();};else {$('#experiment').onsubmit=e=>{e.preventDefault();calculate();};calculate();}}
 if(page==='case')$('#reset').onclick=()=>{if(confirm('Replace this browser’s requests with fresh synthetic data? Export first if needed.')){rows=seed();persist();render();toast('Synthetic demo reset.');}};
}
function calculate(){try{const f=Object.fromEntries(new FormData($('#experiment'))),r=experiment(+f.an,+f.ay,+f.bn,+f.by);$('#experiment-error').textContent='';$('#experiment-result').innerHTML=`<div class="result"><div class="eyebrow">B MINUS A · ABSOLUTE DIFFERENCE</div><strong>${(r.d*100).toFixed(1)} percentage points</strong><p>A: ${pct(r.a)} · B: ${pct(r.b)}</p><p>${r.adequate?`Approximate 95% interval: ${(r.low*100).toFixed(1)} to ${(r.high*100).toFixed(1)} percentage points.`:'Small counts: normal interval withheld. Use an appropriate small-sample method.'}</p><p><b>${!r.adequate?'Insufficient counts for this approximation.':r.low>0?'Positive signal; check design and guardrails before rollout.':r.high<0?'Negative signal; investigate before rollout.':'Inconclusive: interval includes no difference.'}</b></p><p>Hypothetical data. This is not evidence that JanSetu improved completion.</p></div>`;}catch(e){$('#experiment-error').textContent=e.message;$('#experiment-result').innerHTML='';}}
$('#main').onclick=e=>{const btn=e.target.closest('[data-id]');if(btn)openDetail(btn.dataset.id);if(e.target.closest('[data-export]'))download();};
window.addEventListener('hashchange',()=>{render();window.scrollTo(0,0);});render();persist();if(storageWarning)toast('Browser storage unavailable or invalid. Use export to keep session records.');
